def find_anagrams(word):
    anagrams = []
    for i in range(len(word)):
        for j in range(i+1, len(word)+1):
            anagram = word[i:j]
            if sorted(anagram) == sorted(word) and anagram!= word:
                anagrams.append(anagram)
    return anagrams

print(find_anagrams("cat"))

